describe('Success Toast Notification on Record Save', () => {
  beforeEach(() => {
    cy.visit('/records');
  });

  it('should display success toast notification after successfully saving a record', () => {
    // Intercept the save API call
    cy.intercept('POST', '/api/records').as('saveRecord');

    // Fill in the record form
    cy.get('[data-testid="record-name-input"]').type('New Project Alpha');
    cy.get('[data-testid="record-description-input"]').type('A complex new project');
    cy.get('[data-testid="record-status-select"]').select('Active');

    // Click the save button
    cy.get('[data-testid="save-record-button"]').click();

    // Wait for the API call
    cy.wait('@saveRecord');

    // Verify success toast appears
    cy.get('[data-testid="success-toast"]').should('be.visible');
    cy.get('[data-testid="success-toast"]').should('contain', 'Record saved successfully');

    // Verify toast has correct styling and position
    cy.get('[data-testid="success-toast"]').should('have.css', 'opacity', '1');
    cy.get('[data-testid="success-toast"]').should('be.have.css', 'top', '0px');

    // Verify toast has a close button and it works
    cy.get('[data-testid="success-toast-close-button"]').click();
    cy.get('[data-testid="success-toast"]').should('not.exist');

    // Verify record is now visible in the list
    cy.get('[data-testid="record-list"]').should('contain', 'New Project Alpha');
  });

  it('should not display success toast when record save fails', () => {
    // Intercept the save API call and mock a failure response
    cy.intercept('POST', '/api/records', {
      statusCode: 500,
      body: { error: 'Internal server error' }
    }).as('failedSaveRecord');

    // Fill in the record form
    cy.get('[data-testid="record-name-input"]').type('Broken Record');
    cy.get('[data-testid="record-description-input"]').type('This record will fail to save');
    cy.get('[data-testid="record-status-select"]').select('Pending');

    // Click the save button
    cy.get('[data-testid="save-record-button"]').click();

    // Wait for the failed API call
    cy.wait('@failedSaveRecord');

    // Verify success toast does NOT appear
    cy.get('[data-testid="success-toast"]').should('not.exist');

    // Verify error notification appears instead
    cy.get('[data-testid="error-toast"]').should('be.visible');
    cy.get('[data-testid="error-toast"]').should('contain', 'Failed to save record');

    // Verify error toast has correct styling
    cy.get('[data-testid="error-toast"]').should('have.css', 'opacity', '1');
    cy.get('[data-testid="error-toast"]').should('have.css', 'background-color', 'rgb(255, 100, 15)');

    // Verify form is still visible and editable
    cy.get('[data-testid="record-name-input"]').should('be.visible');
  });
});
